#!/usr/bin/env bash
# Verifier driver for step 13 (quiche 0.24.3).
#
# Generated by misc/quic-http3-stack-multiversion/tools/gen-step.py from the
# shared frame plus this step's group list. Edit the frame or the step part and
# regenerate; do not edit one copy in isolation. After Phase 3 opens on a step
# the generated copy becomes authoritative and the reviser edits it directly —
# `tools/carryover-check.sh` is what keeps the fifteen copies honest after that.
set -u
source /tests/helpers.sh

# --- verifier/step binding check -------------------------------------------
# Must be the first thing that runs: /etc/harbor-step-id names the image, the
# literal below names this tests/ tree, and a disagreement means the build
# context was served from another step's cache entry.
require_step 13
# --- end binding check ------------------------------------------------------

# ---------------------------------------------------------------------------
# 0. Crash path.
#
# Under `multi_step_reward_strategy = "mean"` a verifier that exits without a
# reward.json costs the whole trial the steps after it, so every exit from here
# on writes a complete scorecard and exits 0. `fail_everything` is the
# scorecard for a driver that died before it could measure anything.
#
# It reports `gate: 0` with an empty `gate_failures`, and that pairing is the
# signal: a gate of zero with no group named is the driver failing, not a
# candidate regressing. Anything that vetoes a real step names the group and
# quotes what it saw.
# ---------------------------------------------------------------------------
reported=0

fail_everything() {
    local reason="$1"
    printf '{"step":%s,"reward":0.000000,"gate":0,"score":0.000000,"gate_failures":[],"candidate_build":0,"harness_build":0,"fixture_ok":0,"budget_exhausted":0,"crate_dir":"unresolved","build_note":"%s","gate_groups":{},"scored_groups":{}}\n' \
        "${step_num:-0}" "$reason" > /logs/verifier/reward_details.json
    printf '{"reward":0.000000}\n' > /logs/verifier/reward.json
}

on_exit() {
    local status=$?
    if [ "${reported:-0}" -ne 1 ]; then
        fail_everything "the verifier driver exited with status $status before it reported: nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    fi
    exit 0
}
trap on_exit EXIT

step_num=13
step_tag=0.24.3
log_dir=/tmp/quiche-verifier-13
harness=/tmp/quiche-harness-13
assets=/tests/assets
mkdir -p "$log_dir"

# ---------------------------------------------------------------------------
# 1. Fixture integrity.
#
# The verifier-owned corpus — the RFC 9001 Appendix A vectors, the frame and
# QPACK vector files, and the e2e drivers — is a prerequisite for the groups
# that consume it, never a score point of its own. A broken corpus fails those
# groups; it must not short-circuit the independent ones or erase earned
# credit.
# ---------------------------------------------------------------------------
expected_assets_sha=beb6137b9e514c38d0f0219176401940f8489ddacb26f697759815f1e36eeae0
expected_asset_files=43

actual_assets_sha=$(cd "$assets" && find . -type f -print0 | LC_ALL=C sort -z \
    | xargs -0 sha256sum | sha256sum | awk '{print $1}')
actual_asset_files=$(find "$assets" -type f | wc -l)

fixture_ok=1
[ "$actual_assets_sha" = "$expected_assets_sha" ] || fixture_ok=0
[ "$actual_asset_files" -eq "$expected_asset_files" ] || fixture_ok=0

# ---------------------------------------------------------------------------
# 2. Locating the candidate's transport crate.
#
# The library lives at the workspace root until milestone 6 and under
# `quiche/` from milestone 6 onward. Both layouts are accepted everywhere and
# the layout itself is scored by its own group at the step that introduces it,
# so a candidate that has not yet moved the tree loses that one group rather
# than every group in the step. TEST_INTERFACE.md states this probe.
# ---------------------------------------------------------------------------
crate_dir=unresolved
for cand in /app/quiche /app; do
    if [ -f "$cand/Cargo.toml" ] && grep -Eq '^[[:space:]]*name[[:space:]]*=[[:space:]]*"quiche"' "$cand/Cargo.toml"; then
        crate_dir=$cand
        break
    fi
done

workspace_root=/app
[ -f /app/Cargo.toml ] || workspace_root=$crate_dir

# ---------------------------------------------------------------------------
# 2. (continued) Which BoringSSL this tree was written against.
#
# The image pins the library this milestone's release pins, and the environment
# names it. At most steps that is the only copy and this loop does nothing.
#
# Where the QUIC callback struct changed shape across a step boundary, the
# image carries the previous release's pin as well. `SSL_QUIC_METHOD` is a
# struct of function pointers passed to `SSL_set_quic_method`: releases up to
# 0.1.0 declare four members, beginning `set_encryption_secrets`; from 0.3.0
# they declare five, beginning `set_read_secret` and `set_write_secret`. A tree
# of the older shape handed to a library of the newer one links cleanly -- the
# symbol exists and takes a pointer -- and then reads one member past the end
# of the struct, calling the wrong function for every callback. Nothing errors.
# The handshake simply never emits a ClientHello, and the step's inherited
# regression groups fail for a linkage reason wearing behaviour's clothes.
#
# So the shape is read out of the candidate's own `src/tls.rs` and the matching
# library selected. The test is deliberately two-sided -- the old name present
# AND the new names absent -- so a tree part-way through the conversion, or one
# that merely mentions the old name in a comment, keeps this release's library.
# The shape is read out of *live code*: `//` comments are stripped before the
# two greps run, so a migration note naming the old field cannot flip the pick.
# A candidate who does the work is unaffected: the environment already names
# the right one, and this loop never fires. It cannot manufacture a pass for
# the scored groups either; those ask for behaviour this milestone introduced,
# which no older library supplies.
#
# `.cargo/config.toml` in the workdir sets the same variable through cargo's
# `[env]` table, which without `force = true` yields to a variable already set
# in the environment -- so exporting here is enough, and the file stays honest
# about the default.
# ---------------------------------------------------------------------------
if [ -n "${QUICHE_BSSL_PATH:-}" ] && [ -f "$crate_dir/src/tls.rs" ] &&
    sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_encryption_secrets' &&
    ! sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_read_secret'; then
    for alt in /opt/bssl/*; do
        [ -d "$alt" ] || continue
        [ "$alt" = "$QUICHE_BSSL_PATH" ] && continue
        QUICHE_BSSL_PATH=$alt
        export QUICHE_BSSL_PATH
        break
    done
fi

# ---------------------------------------------------------------------------
# 2a. The time budget, and why these numbers.
#
# `task.toml` gives this step `[steps.verifier] timeout_sec = 3600`. If the
# verifier is killed by that timeout it never writes reward.json and the run is
# unattributable rather than a zero, so the work inside must provably fit
# whatever the candidate does:
#
#   verify the pinned asset corpus                               <   5 s
#   CANDIDATE_BUILD_TIMEOUT  one `cargo build` of /app, cold    <= 1000 s
#   EXAMPLES_BUILD_TIMEOUT   the best-effort examples pass      <=  240 s
#   APPS_BUILD_TIMEOUT       the best-effort app-package pass   <=  240 s
#   HARNESS_BUILD_TIMEOUT    one `cargo test --no-run` of the
#                            verifier-owned harness crate       <=  800 s
#   CASE_BUDGET_TOTAL        every gate check and every scored
#                            group together                     <= 1200 s
#   write the two JSON files                                     <   5 s
#                                                    worst case   3490 s
#
# PER_CASE_MAX is far above any real case and far below the aggregate: one
# hanging case costs its own group and at most 120 s of the shared pool, so a
# step with many hanging cases degrades group by group instead of taking the
# run down. BoringSSL and the whole dependency graph are prebuilt into the
# image, so the candidate build is the candidate's own code and nothing else.
CANDIDATE_BUILD_TIMEOUT=1000
EXAMPLES_BUILD_TIMEOUT=240
APPS_BUILD_TIMEOUT=240
HARNESS_BUILD_TIMEOUT=800
CASE_BUDGET_TOTAL=1200
PER_CASE_MAX=120

# ---------------------------------------------------------------------------
# 3. Build the candidate workspace once, before anything is scored.
#
# Recorded separately from the groups: every group runs against this build, so
# one compile error would otherwise be reported as N unrelated capability gaps.
# ---------------------------------------------------------------------------
candidate_build=0
if [ "$crate_dir" != unresolved ]; then
    # Default targets only -- libraries and binaries. Deliberately not
    # `--all-targets`: that would also compile the candidate's own test and
    # bench targets, so a broken test of theirs would fail the build and be
    # reported as every capability missing at once. Their tests are not what
    # this verifier measures.
    (cd "$workspace_root" && timeout "$CANDIDATE_BUILD_TIMEOUT" \
        cargo build --offline -j 4) \
        >"$log_dir/candidate-build.log" 2>&1 && candidate_build=1
    # The client and server lived under examples/ before they became their own
    # package. Best-effort and never fatal: at releases where they are bins the
    # build above already produced them, and at releases where there are no
    # examples this is a no-op.
    if [ "$candidate_build" -eq 1 ]; then
        (cd "$workspace_root" && timeout "$EXAMPLES_BUILD_TIMEOUT" \
            cargo build --offline --examples -j 4) \
            >"$log_dir/candidate-examples.log" 2>&1 || true
    fi
    # Later they moved out of examples/ and into a package of their own --
    # `tools/apps` first, then `apps`. Where that package is a workspace member
    # the build above already covered it; where it exists but the root manifest
    # has no [workspace] section, cargo never descends into it, so the tree
    # ships the client and server sources and produces neither binary. Building
    # the package where it sits covers that window, and builds more of the
    # candidate rather than asking less of it.
    #
    # Best-effort, like the examples pass, and bounded as one pass rather than
    # one per path: at a release whose lockfile predates this package's own
    # dependencies it cannot resolve offline at all, which is a property of the
    # pinned corpus and not a candidate defect. Building a non-member package
    # makes cargo write a lockfile beside its manifest; no group reads one.
    if [ "$candidate_build" -eq 1 ]; then
        apps_deadline=$(( $(date +%s) + APPS_BUILD_TIMEOUT ))
        for app in tools/apps apps; do
            [ -f "$workspace_root/$app/Cargo.toml" ] || continue
            left=$(( apps_deadline - $(date +%s) ))
            [ "$left" -gt 0 ] || break
            (cd "$workspace_root/$app" && timeout "$left" \
                cargo build --offline -j 4) \
                >"$log_dir/candidate-app-$(printf '%s' "$app" | tr / -).log" \
                2>&1 || true
        done
    fi
fi

# The client and server binaries are the process boundary most groups use.
# The harness resolves them itself, by name, from the CANDIDATE_* variables
# below -- the names are the step's own interface section's, and the harness
# applies them name-major over the directories it searches. The driver does
# not pre-resolve a binary and does not prefer any spelling of its own: a
# second resolution rule written here could only ever disagree with that one.
target_dir=${CARGO_TARGET_DIR:-$workspace_root/target}

export QUICHE_CRATE_DIR="$crate_dir"
export QUICHE_WORKSPACE="$workspace_root"
export QUICHE_ASSETS="$assets"
export QUICHE_LOGDIR="$log_dir"

# What `verifier::testkit` reads. The harness has to find the candidate's
# binaries, and in this image they are not under /app/target: CARGO_TARGET_DIR
# is set image-wide so the prewarmed dependency graph is reused, which moves
# every artefact to /opt/cargo-target. Telling the harness where the tree and
# the artefacts actually are keeps that an image detail instead of something
# each of the fifteen steps' test files has to know.
export CANDIDATE_ROOT="$workspace_root"
export CANDIDATE_TARGET_DIR="$target_dir"
# Scratch directories are deliberately never cleaned up: when a case fails, the
# document root, the captured stdout and the server log it left behind are the
# evidence. Rooting them in the log directory keeps them beside the case log.
export VERIFIER_SCRATCH="$log_dir/scratch"
mkdir -p "$VERIFIER_SCRATCH"

# ---------------------------------------------------------------------------
# 4. The throw-away harness crate.
#
# It lives outside /app so that a candidate cannot make its own acceptance pass
# by editing the cases, and so that nothing the harness needs is ever added to
# the candidate's manifest. It declares exactly one dependency — a path
# dependency on the candidate's own transport crate — so a harness build
# failure is always about the candidate's public surface and never about a
# registry.
# ---------------------------------------------------------------------------
# Does the candidate's manifest declare a Cargo feature by this name?
#
# Either an explicit entry under [features], or an optional dependency of the
# same name, which Cargo turns into a feature implicitly.
# Does the candidate's manifest declare `$2` as a feature?
#
# Three spellings are legal Cargo for "this crate can be built with a `qlog`
# feature", and all three have to be recognised or a correct manifest is read
# as not declaring it, the feature is dropped from the harness's own edge, and
# every `cap` group fails to link for a reason that is not the candidate's:
#
#   [features]
#   qlog = []
#
#   [dependencies]
#   qlog = { version = "..", optional = true }
#
#   [dependencies.qlog]
#   optional = true
#
# The third puts the name in the section header and never in field 1, which is
# why the spelling is tracked as well as the key.
declares_feature() {
    awk -v want="$2" '
        /^[[:space:]]*\[/ {
            sec = $1
            gsub(/^\[|\]$/, "", sec)
            section = sec
            dep_table = (sec == "dependencies." want || sec == "dev-dependencies." want \
                         || sec == "build-dependencies." want)
            next
        }
        $1 == want && $2 == "=" && section == "features" { found = 1 }
        $1 == want && $2 == "=" && section ~ /dependencies$/ \
            && $0 ~ /optional[ \t]*=[ \t]*true/ { found = 1 }
        dep_table && $1 == "optional" && $2 == "=" && $3 == "true" { found = 1 }
        END { exit found ? 0 : 1 }
    ' "$1"
}

prepare_harness() {
    rm -rf -- "$harness"
    mkdir -p "$(dirname "$harness")"
    # The whole tree, not a hand-listed subset: the harness is a two-member
    # workspace (the verifier crate and `support/`, the independent QUIC
    # implementation) and it carries its own `assets/` — the TLS keypair and
    # the RFC vectors the cases load through `testkit::asset`. Copying file
    # patterns instead would silently drop whichever of those a future step
    # starts using, and the resulting build failure would be charged to the
    # candidate.
    cp -a -- "$assets/harness" "$harness"
    # The only edit: the candidate's crate path, which is not known until the
    # probe above has run. Resolved here rather than in the checked-in manifest
    # so the manifest stays identical in all fifteen steps.
    sed -i "s#@@CRATE_DIR@@#$crate_dir#g" "$harness/Cargo.toml"
    # Optional feature requests, resolved against the candidate's own manifest.
    #
    # Cargo validates every feature reference while it resolves the graph,
    # before it compiles anything, so asking a milestone for a feature it does
    # not declare fails the whole harness build -- including the gate targets,
    # which never touch the feature. Names marked `# optional-feature:` in the
    # harness manifest are therefore kept only when the candidate declares
    # them. The scored case that needs one then fails to compile by itself,
    # which is the right answer for a candidate that has not built it.
    for feat in $(sed -n 's/^#[[:space:]]*optional-feature:[[:space:]]*//p' \
        "$harness/Cargo.toml"); do
        if declares_feature "$crate_dir/Cargo.toml" "$feat"; then
            printf 'kept optional feature %s\n' "$feat" \
                >>"$log_dir/harness-features.log"
        else
            sed -i "s/\"$feat\"[[:space:]]*,[[:space:]]*//; s/,[[:space:]]*\"$feat\"//; s/\"$feat\"//" \
                "$harness/Cargo.toml"
            printf 'dropped optional feature %s: the candidate does not declare it\n' \
                "$feat" >>"$log_dir/harness-features.log"
        fi
    done
    # No lockfile, on purpose. One authored against the reference tree would
    # pin the candidate's own dependency versions, turning a legitimate
    # difference in their manifest into a harness build failure that reads as
    # their fault. The registry cache is prewarmed, so resolving offline here
    # costs nothing.
    rm -f -- "$harness/Cargo.lock"
}

harness_build=0
if [ "$candidate_build" -eq 1 ]; then
    prepare_harness
    (cd "$harness" && timeout "$HARNESS_BUILD_TIMEOUT" \
        cargo test --offline --no-run -j 4) \
        >"$log_dir/harness-build.log" 2>&1 && harness_build=1
fi

# The case pool starts here, so a slow build cannot eat it.
case_deadline=$(( $(date +%s) + CASE_BUDGET_TOTAL ))
budget_exhausted=0

# remaining_budget -> seconds left in the shared pool, or 0
remaining_budget() {
    local r=$(( case_deadline - $(date +%s) ))
    [ "$r" -lt 0 ] && r=0
    printf '%s\n' "$r"
}

# run_case <log-name> <test-target> <test-fn>
#
# Each case is bounded by the smaller of PER_CASE_MAX and what is left of
# CASE_BUDGET_TOTAL, so the cases can never overrun that total however many of
# them hang. A killed case exits non-zero and scores that one group 0, which is
# the same outcome as any other failure; once the pool is spent the remaining
# groups are failed without running and the reason is recorded, which is still a
# zero rather than a lost run.
run_case() {
    local name="$1" target="$2" fn="$3" remaining limit status
    remaining=$(remaining_budget)
    if [ "$remaining" -le 5 ]; then
        budget_exhausted=1
        printf 'the aggregate case budget of %s s was exhausted before this case ran\n' \
            "$CASE_BUDGET_TOTAL" >"$log_dir/$name.log"
        return 1
    fi
    if [ ! -d "$harness" ]; then
        # The harness crate is assembled only after a candidate transport crate
        # has been located. When it was not, every case here would fail on `cd`
        # with a shell error in its log, which reads as a broken driver rather
        # than as a result. The group does fail -- but for a definite reason,
        # and the reason belongs on the group that fired it.
        {
            printf 'the harness crate was never assembled, so this case could not run.\n'
            printf 'assembly is skipped when no candidate transport crate was located\n'
            printf '(crate_dir=%s): there was nothing for the harness to link against.\n' "$crate_dir"
            printf 'This group fails for that reason, not for anything it asserts.\n'
        } >"$log_dir/$name.log"
        return 1
    fi
    limit=$PER_CASE_MAX
    [ "$remaining" -lt "$limit" ] && limit=$remaining
    (cd "$harness" && timeout "$limit" \
        cargo test --offline --test "$target" "$fn" -- --exact --nocapture) \
        >"$log_dir/$name.log" 2>&1
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    # Every invocation asserts an exact executed count: a name filter that
    # matches nothing still exits 0, and would otherwise be scored as a pass.
    grep -q 'test result: ok\. 1 passed; 0 failed; 0 ignored' "$log_dir/$name.log"
}

# ---------------------------------------------------------------------------
# 5. The gate.
#
# Proof of life plus inherited regression: that the candidate builds, that its
# two binaries still complete a handshake and a transfer over real UDP, and
# that one deterministic end-to-end path per earlier milestone still works.
#
# Gate groups earn nothing. They only veto: if any one of them fails the step
# is worth zero however much of this step's own capability landed. That is
# deliberate. A candidate that implements this release by breaking the last one
# has not advanced the ladder, and an additive score would pay it for the parts
# that still happen to work.
#
# The corollary governs what is allowed in here. A gate case that can fail for
# a reason other than the candidate's code -- a wall clock, a host's CPU count,
# an unordered iteration read as ordered -- is not weak coverage, it is a step
# that randomly scores zero for everyone including the reference. Every case
# below is deterministic, and the ones that were not were deleted rather than
# demoted; NOTES.md lists them and why.
#
# Behaviour this step deliberately changes is likewise not in here. A migration
# left in the gate is a step whose own reference implementation fails it.
# ---------------------------------------------------------------------------
gate_ok=1
gate_log=$log_dir/gate.txt
: > "$gate_log"

gate_check() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$gate_log"
    else
        printf 'FAIL %s\n' "$name" >> "$gate_log"
        gate_ok=0
    fi
}

candidate_builds() { [ "$candidate_build" -eq 1 ]; }

# Every other gate group is a case or a driver and leaves `$log_dir/<name>.log`
# behind, which is where the scorer reads the reason a veto fired. This one is
# a flag set back in section 3, so give it the log the flag came from.
if [ -f "$log_dir/candidate-build.log" ]; then
    cp -f "$log_dir/candidate-build.log" "$log_dir/candidate-workspace-builds.log"
else
    # Section 3 runs cargo only when a quiche crate was located. When it was
    # not, no candidate-build.log exists, and copying it silently left this
    # group with no log at all -- which the scorer reports as "the case did not
    # run". That reads like a harness that failed to fire, when in fact the
    # group failed for a definite reason. A veto must carry its reason on the
    # group that fired it, so write it here rather than leave the scorer to
    # guess. The step-level build_note says the same thing; this puts it where
    # a reader looks first.
    {
        printf 'no cargo build was attempted: crate_dir=%s\n' "$crate_dir"
        printf 'no Cargo.toml declaring the package name `quiche` was found at\n'
        printf '/app or /app/quiche, so there was no transport crate to build.\n'
        printf 'This group fails by definition: proof-of-life cannot pass when\n'
        printf 'the candidate shipped no library to prove alive.\n'
    } > "$log_dir/candidate-workspace-builds.log"
fi
gate_check candidate-workspace-builds candidate_builds
# T3: Carried as this step's plan-mandated re-check of a step-5 hot-path observation. `RecvInfo` is the descriptor every inbound datagram is delivered with, and it is on the receive path of every connection in the package. This step replaces the type that path lives on -- `Connection` becomes `Connection<F>` -- and adds a second, independent stack on top of it, so if either of those rebuilt the receive path, the address descriptor is where it shows first. Two halves: * **The type.** `RecvInfo { from, to }` values compare equal to themselves and unequal when either field differs. Step 05 asserted this over a single-field `RecvInfo { from }`; the type gained `to` at a later release, so the carried assertion is widened to both fields rather than dropped. That is the only adaptation, and it is an adaptation of the *same* observation. * **The hot path.** A 4 KiB `client_to_server` transfer, and then, over every `SendInfo` the exchange produced at both ends, `info.to` is the address the datagram was actually addressed to -- the server's address for client-side sends, the client's for server-side sends. **Deliberately clock-free.** Step 05's sibling observation `cap-sendinfo-at` read `SendInfo::at`, a wall-clock instant, and was removed from the gate at steps 07 and 11 under the determinism rule: a gate group is an unpriced veto, so anything in it that could read differently under load costs every candidate the whole step. It stays removed here, and nothing in this case reads a clock, a duration or a timer.
gate_check reg-05-recvinfo-from run_case reg-05-recvinfo-from reg reg_05_recvinfo_from
# T3: Carried because this step adds a fifth entry to the very enum that group was about. The failure mode it guards is specific and likely: appending a variant is the moment a name table, a discriminant or an exhaustive match gets rewritten, and a rewrite that gets the *new* entry right while disturbing an old one would otherwise be scored only by the group that was looking at the new entry. * **Names.** `"bbr2"` maps to `Ok(())` and selects `BBR2` -- not the gcongestion variant, and not a default. `"BBR2"`, `"bbr2 "`, `"bbr3"` and `""` are each `Err(Error::CongestionControl)`, as they were at step 10: the lookup does not case-fold, does not trim, and does not fall through. `reno`, `cubic` and `bbr` still resolve. * **Discriminants.** `(Reno, CUBIC, BBR, BBR2)` as `u32` is still `(0, 1, 2, 3)`. The new variant is checked where it belongs, in `cap-gcongestion-bbr2`; what this group asserts is that adding it moved nothing. * **That it still carries data.** Both selection routes -- by name and by variant -- are handshaked and each carries a 256 KiB transfer that arrives byte-for-byte with its fin, and `stats().sent_bytes` is at least the payload length. The `sent_bytes` bound is one-sided on purpose. An exact figure depends on how the send path chunked the transfer and on retransmission, neither of which a gate group may assert; "at least what we handed it" is true of every correct implementation and false of one that dropped the data.
gate_check reg-10-bbr2 run_case reg-10-bbr2 reg reg_10_bbr2
# T1: The end-to-end connection-migration path, run between the candidate's own `quiche-server` and `quiche-client`. The client is given `--no-verify` and `--perform-migration` and asked for a 512 KiB file. It must exit 0 within the group's deadline and write the file out byte-for-byte. That is the whole assertion. Carried because migration exercises path validation, connection-ID retirement and the address descriptors on both the send and receive paths at once, and because this step rebuilds the type those paths hang off. It is also the only gate group other than `gate-endtoend` that runs the two real binaries, so it is what would notice a workspace that builds but whose `apps` member no longer links. **The socket-sampling leg is deliberately absent.** Step 10's copy of this group counted locally bound UDP ports and required at least two at once, to witness the migration rather than merely its result. That leg was removed upstream under the determinism rule -- the sample is a race against the client's own socket lifetime -- and it stays removed. What survives is the one-sided, deterministic half: a migrating client that completes its transfer. The case takes the harness's T1 serial guard.
gate_check reg-08-probe-and-migrate run_case reg-08-probe-and-migrate reg reg_08_probe_and_migrate
# T1: Proof of life, and nothing else. The candidate's own `quiche-server` is started on a loopback port with `--listen`, `--cert`, `--key`, `--root` and `--no-retry`; its own `quiche-client` fetches one file from it with `--no-verify`; the client exits 0 and the bytes it wrote match the file the server was serving, byte-for-byte. Every other option is the reference's own default. Nothing from this step's milestone appears here on purpose -- no `tokio-quiche`, no buffer factory, no zero-copy send, no fifth congestion controller. Those are scored where they can be seen. This group is the floor underneath all of them, and it is the group that fails first if the workspace's growth from five members to nine broke the build of the two binaries that were already there, or if the root manifest's new inherited-dependency tables are malformed. It earns nothing. Under `reward = gate x score` it can only veto.
gate_check gate-endtoend run_case gate-endtoend gate gate_endtoend

# ---------------------------------------------------------------------------
# 6. The scored groups.
#
# This step's new capability, plus peripheral breadth. Each group is one
# coherent behaviour and is invoked separately, so a failure localises, and
# every group runs even after another has failed: a partial implementation
# keeps exactly the credit it earned.
#
# Weights live in `/tests/groups.json` and sum to one across the groups here,
# so this step's score is in [0, 1] and is the weighted fraction of its own new
# behaviour that works. Nothing in this section knows a weight -- it records
# PASS or FAIL per group and the scorer prices it -- so a revision that edits a
# group here cannot silently desync the driver from the manifest.
# ---------------------------------------------------------------------------
group_log=$log_dir/groups.txt
: > "$group_log"

score_if() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$group_log"
    else
        printf 'FAIL %s\n' "$name" >> "$group_log"
    fi
}

# T1: The new workspace member, used the way a consumer would use it, against the candidate's own client. The verifier writes a small crate into scratch -- a `Cargo.toml` with its own empty `[workspace]` table so it does not get pulled into the candidate's, a path dependency on `<candidate root>/tokio-quiche`, `tokio` with `rt` and `macros`, and `futures` -- and a `main.rs` of about sixty lines that binds a `std::net::UdpSocket`, calls `listen` with `ConnectionParams::new_server`, `SimpleConnectionIdGenerator` and `DefaultMetrics`, and answers every `H3Event::IncomingHeaders` with `:status 200` and a fixed body. That crate is the observation instrument; building it is the first assertion, because a `tokio-quiche` whose public surface is not the one the interface document fixes does not compile against it. It is built with `cargo build --offline -j 4` and with `CARGO_TARGET_DIR` pointed at the same target directory the driver already used for the candidate's workspace, so every one of the crate's dependencies is already compiled and the probe build is a link rather than a rebuild -- measured at about 20 seconds cold and nothing thereafter, against the group's per-case ceiling. Then the two halves meet. The probe is spawned as a server on a free loopback port with the fixture certificate and key; the candidate's **own** `quiche-client` is run at it with `--no-verify --http-version HTTP/3` and a `https://127.0.0.1:<port>/probe.bin` URL. Four assertions, in order: * the client did not hit its deadline; * the client exited 0; * the probe's stderr contains `path=/probe.bin`, which is the server's report of the `:path` pseudo-header it actually received -- so the request reached the application layer and was decoded, not merely accepted at the transport; * the bytes the client wrote out are exactly the 4096-byte fixed pattern the probe sent, compared by length first and then byte-for-byte. The `path=` line is the probe's own output, written by the verifier's own source, so it is not a claim about the candidate's logging. Nothing is asserted about `tokio-quiche`'s tracing, its metrics values, or its client side; the client path, the datagram surface, and the connection hooks are all out of scope for this step's observation. The case takes the harness's T1 serial guard, because it binds a port and runs two processes.
score_if cap-tokio-quiche run_case cap-tokio-quiche cap cap_tokio_quiche
# T3: That `Connection<F>` is generic in more than its signature: the buffers really come from the factory the caller named. The harness supplies `CountingFactory`, whose `buf_from_slice` increments a thread-local counter and whose buffer holds its bytes behind an `Arc`, and `PrefixFactory`, a second factory of a different Rust type. Both are built out of the crate's own `BufFactory`/`BufSplit`, so the group fails to compile at all if those traits are not exported from the crate root -- which is the first thing it is measuring. Three legs over a 48 KiB stream transfer, all through `connect_with_buffer_factory`/`accept_with_buf_factory` and the ordinary `send`/`recv`/`stream_send`/`stream_recv` loop: * **both ends on `CountingFactory`** -- the server reassembles the payload byte-for-byte and sees the fin, *and* the counter is strictly higher after the transfer than before. A candidate that accepted the type parameter and then routed through its own default storage passes the first half and fails the second. * **both ends on plain `connect`/`accept`** -- the transfer still works and the counter does **not** move. This is the control: without it, a counter that was being bumped by something ambient would make leg 1 vacuous. * **client on `CountingFactory`, server on `PrefixFactory`** -- the bytes still agree. The factory is a local storage decision; nothing about it is negotiated or visible on the wire, and the two ends of a connection are free to disagree. `DefaultBufFactory` is deliberately never named. The harness cannot name it -- it is not exported -- and the group is built so that it does not need to: the default is reached by writing `Connection`, and a custom one by naming the harness's own type. Not asserted: how many buffers the factory is asked for, what sizes they are, or when. Those are scheduling details of the send path and would make the group a statement about an implementation's chunking rather than about the type parameter.
score_if cap-generic-connection run_case cap-generic-connection cap cap_generic_connection
# T3: The fifth congestion controller, pinned at four levels: the discriminant, the name, the accessor, and whether it actually moves bytes. **Discriminants.** `Reno as u32 == 0`, `CUBIC == 1`, `BBR == 2`, `BBR2 == 3`, `Bbr2Gcongestion == 4`. The enum is `#[repr(C)]` and crosses the FFI boundary, so the four older values must be unchanged and the new one appended rather than inserted. `BBR2 != Bbr2Gcongestion` as values, because they are two different algorithms that happen to share a name in prose. **Names.** `set_cc_algorithm_name` accepts each of `reno`, `cubic`, `bbr`, `bbr2` and `bbr2_gcongestion` with `Ok(())`, and answers `Err(Error::CongestionControl)` for `bbr3_gcongestion` -- a near-miss chosen deliberately over an obviously absurd string, because the failure this catches is a lookup that falls through to a default when it does not recognise a name. **The accessor.** Three pairs that differ in exactly one line, each fully handshaked, each asked `gcongestion_enabled()` at both ends. The answers must be `(CUBIC, false)`, `(BBR2, false)`, `(Bbr2Gcongestion, true)` -- in that order, as a whole -- and the two ends of each pair must agree with each other, since both were configured the same way. `bbr2` mapping to `false` is not incidental: the crate is built with its default features, `gcongestion` is not among them, so the legacy implementation is what that name selects and the group would be wrong to expect otherwise. **That it works.** Each of the three pairs then carries a 256 KiB transfer, which must arrive byte-for-byte with its fin and leave neither end closed. A variant that parses and then cannot move data is not the feature. Not asserted: any throughput, timing or window figure. What separates BBRv2 from the gcongestion BBRv2 at runtime is pacing and window dynamics, and neither is something a bounded in-process case can measure without becoming a benchmark.
score_if cap-gcongestion-bbr2 run_case cap-gcongestion-bbr2 cap cap_gcongestion_bbr2
# T3: The zero-copy stream send, and specifically the part of it that an implementation could fake. Over a handshaked `Connection<CountingFactory>` pair: * **The explicit length is honoured exactly.** A 48 KiB buffer is sent with `len = Some(1000)` on a connection whose capacity is far larger, so nothing but the caller's own limit can be binding: the call returns `1000`, the remainder is `Some`, its length is `payload.len() - 1000`, and its bytes are the tail of the buffer that was handed over. * **The remainder is the caller's buffer, not a copy of it.** A second send of the whole buffer with `len = None` must be partial -- the payload is deliberately larger than a fresh connection's capacity -- and the harness keeps a clone of the buffer before giving it away. `CountingBuf::clone` shares the allocation, so `Arc::ptr_eq` between that witness and the returned remainder is the zero-copy claim itself. An implementation that copied the unsent bytes into storage of its own and rebuilt a buffer from a slice returns the right bytes in the wrong allocation and fails here. * **The arithmetic closes.** The transfer is then finished by feeding the remainder back through the same call in a bounded loop, and on every round the bytes written plus the remainder's length equal what was handed over. `Error::Done` is a retry, not a failure. * **The bytes arrive.** The stream is closed with an empty `stream_send(.., true)` and the server reassembles the full 48 KiB byte-for-byte with its fin. * **`fin` lands at the offset the call reached.** The buffer goes out once more, on a fresh stream, with `len = Some(1000)` and `fin = true`. The call returns a tail, and the peer must then see exactly 1000 bytes on that stream **with the fin**: an explicit length is the caller's own limit, not a capacity truncation, so it does not demote `fin`. Offering the returned tail to a further call is then `Err(FinalSize)` -- those bytes are past the final size the stream just committed to. The partiality is forced with an explicit length rather than by leaning on the send capacity, so this says the same thing on a loaded host as on an idle one. * **The errors are the ones `stream_send` already returns.** Two of them are driven directly. A send on stream 3 -- server-initiated, unidirectional, and this is the client -- is `Err(InvalidStreamState(3))`, naming the stream the call was made on. A send on a stream the peer has shut down with a STOP_SENDING is `Err(StreamStopped(code))` carrying **the peer's code**. The particular code is this case's own choice, held in a `const` and deliberately not written down here: what is asserted is that the number the peer shut the stream down with is the number that comes back, and a contract that named it would let an implementation return *that* number instead of carrying the peer's. Not asserted: how large each accepted chunk is, or how many rounds the loop takes. Both follow from the congestion window at each moment and neither is part of the contract; the loop only carries a sanity bound so that a non-progressing implementation fails as a stall rather than as a hang. Nor is `Error::Done` driven deliberately -- it arrives on its own during the transfer loop, where it is treated as a retry.
score_if cap-stream-send-zc run_case cap-stream-send-zc cap cap_stream_send_zc
# T3: Both branches of the HTTP/3 zero-copy body send, and that they are indistinguishable to the peer. `send_body_zc` asks the caller's buffer to grow the DATA frame header on its front via `BufSplit::try_add_prefix`. The harness supplies one factory whose buffers accept a prefix (`PrefixFactory`) and one whose buffers refuse it (`CountingFactory`, which takes the trait's default implementation and returns `false`), and runs the same 3 KiB body through a complete HTTP/3 request/response over a `Connection<F>` pair on each. * **The count excludes the header.** Both legs must report exactly the body length. The prefix-accepting branch writes more bytes to the stream than the application supplied, and reporting that larger number would be reporting bytes the caller never asked to send; the case fails a candidate that forgot to subtract the prefix. * **Both legs deliver the body.** The client's `h3::Event::Data` yields the 3 KiB byte-for-byte in each leg. * **The two branches agree.** The bytes from the accepting leg and the bytes from the refusing leg compare equal to each other, so a candidate that ignored `try_add_prefix` and always wrote the header separately still has to produce the same wire bytes -- and one that mis-framed only the in-place branch fails this comparison even if each leg were somehow self-consistent. The exchange runs on `ALPN_H3` and confirms `application_proto() == b"h3"` before sending anything, so an HTTP/3 assertion cannot be made against a connection that negotiated something else. * **The header section has to have gone first.** On a third pair, the server polls the request and then calls `send_body_zc` without having called `send_response`: that must be `Err(h3::Error::FrameUnexpected)`, the documented variant and not a generic failure. The same call then succeeds once the response headers have gone, on the same stream with a buffer of the same kind -- so the leg is about the ordering rule and not about the stream or the buffer being wrong in some other way. Not asserted: the DATA frame's bytes as seen on the wire, or how many `stream_send` calls each branch made. The distinction between the branches is an allocation strategy; the only thing that may differ observably is nothing.
score_if cap-h3-send-body-zc run_case cap-h3-send-body-zc cap cap_h3_send_body_zc
# T3: That the send capacity factor scales what a single `stream_send` will accept, exactly and not merely monotonically. Four freshly handshaked pairs, identical but for one line, each handed the same 512 KiB payload in one `stream_send` -- a payload deliberately larger than any of the capacities involved, so every measurement is capacity-bound rather than payload-bound: | configuration | accepted | | --- | --- | | factor unset | `n` | | `set_send_capacity_factor(1.0)` | `n` | | `set_send_capacity_factor(2.0)` | `2 * n` | | `set_send_capacity_factor(4.0)` | `4 * n` | with `0 < n < 512 KiB`. The unset row and the 1.0 row must be equal, which is how the documented default of 1 is checked without reading it back. The 2.0 and 4.0 rows are exact multiples, which is what distinguishes an implementation that multiplies from one that merely enlarges a buffer somewhere. A fifth pair at factor 2.0 then carries a 128 KiB transfer to completion, byte-for-byte with its fin, so that a factor which produced a bigger number and a broken connection does not pass. Not asserted: any effect on throughput, on the congestion window, or on what leaves the socket. The factor governs how much the application may hand over before being told to wait, and a case that claimed more would be claiming the congestion controller had been overridden.
score_if cap-send-capacity-factor run_case cap-send-capacity-factor cap cap_send_capacity_factor
# T3: The two HTTP/3 priority additions, held to their documented contracts over a `Connection<CountingFactory>` -- because the whole `h3` API became generic in the buffer factory in the same release, and a group that used the default connection would not notice if it had not. **`Priority` as a value type.** A `Priority` is assigned away and the original is still usable afterwards, which only compiles if it is `Copy`; it is cloned; `Priority::default()` equals `Priority::new(3, false)`, the default urgency the specification names; and `Priority::new(5, true) != Priority::new(5, false)`, so equality covers the incremental flag and not only the urgency. **`send_additional_headers_with_priority`.** Over a complete HTTP/3 exchange: * called by the server **before** any initial header section on that stream -- `Err(h3::Error::FrameUnexpected)`; * called after the response headers, with `is_trailer_section = true` and a `Priority` built at **urgency 200** -- `Ok(())`. Urgency is a three-bit field, so this is the clamp: the value is pinned to 7 before the internal offset of 124 is added, and nothing overflows. A candidate that rejected the value, or that added 200 to 124 and wrapped, fails here; * called a **second** time with `is_trailer_section = true` -- `Err(h3::Error::FrameUnexpected)`, because a stream carries at most one trailer section; * called by the **client** with `is_trailer_section = false` -- `Err(h3::Error::FrameUnexpected)`, because an additional non-trailing section is a response construct. **What the peer sees.** The client is then drained, and must observe exactly two header sections on the request stream -- the `:status 200` response section first, then the trailer section with its name/value pairs verbatim -- followed by `h3::Event::Finished`. Two, not three: the refused calls must have put nothing on the wire. Not asserted: any scheduling consequence of the priority. The specification is explicit that priority parameters are a suggestion a server need not act on, and there is nothing for a single-request case to observe even if it did.
score_if cap-h3-priority-helpers run_case cap-h3-priority-helpers cap cap_h3_priority_helpers
# T4: The shape of the workspace itself, read the way cargo reads it. First, cheaply: a `Cargo.toml` must exist at each of the four new members -- `buffer-pool`, `datagram-socket`, `task-killswitch`, `tokio-quiche` -- and at each of the five carried ones -- `apps`, `h3i`, `octets`, `qlog`, `quiche`. This runs before the metadata call so that a missing directory is reported as a missing directory rather than as a cargo error. Then authoritatively: ``` cargo metadata --offline --no-deps --format-version 1 --manifest-path <root>/Cargo.toml ``` with `CARGO_TARGET_DIR` in scratch. Each of the nine names must appear in the `workspace_members` array, and the array must have **exactly nine** entries -- an extra member fails as surely as a missing one, because the membership list is the thing being observed and a candidate that added a tenth crate of its own has not reproduced this release's workspace. Member entries are matched by package name against the id syntax cargo emits, accepting both the `path+file://...#name@version` and `...#name` spellings, so the group does not break on a cargo whose id format changed. The metadata call proves membership and only membership. It does **not** stand in for a check of the root manifest's own tables: `--no-deps` asks cargo for the workspace's package list, and a candidate that wrote literal values into every member manifest instead of inheriting them produces exactly the same nine-member list whether the root declares `[workspace.package]` at all. Nor can it say anything about dependency edges, which `--no-deps` omits by construction. So the group reads two things off the manifests directly, with whole-line comments stripped first: * the root manifest carries `[workspace.package]` and `[workspace.dependencies]` and sets `resolver` to `"2"` -- either TOML string spelling, any spacing; * `quiche/Cargo.toml` names none of `buffer-pool`, `datagram-socket`, `task-killswitch` or `tokio-quiche`, in any dependency table. Not asserted: dependency versions, feature lists, edition, or any member's internal structure, and nothing at all about what the four new manifests contain beyond existing. The group's claim is the shape of the workspace -- which crates are in it, what the root hands down, and which way the one dependency that matters points. The rest is scored where it can be seen behaving.
score_if cap-async-workspace run_case cap-async-workspace cap cap_async_workspace

# ---------------------------------------------------------------------------
# 7. Report.
#
#     reward = gate x score
#
# `score.py` does the arithmetic against the manifest, because the two checks
# that matter are both about groups going missing -- a declared group with no
# recorded result, or a recorded result for a group nobody priced -- and both
# are easier to get right over parsed JSON than over shell word splitting. It
# prints the reward and writes reward_details.json, naming the gate group that
# vetoed the step and quoting what it saw.
#
# If it cannot run at all, that is a verifier defect and not a capability
# result, and the crash path in section 0 says so in those words.
# ---------------------------------------------------------------------------
score_input=$(printf '{"step_num":%d,"tag":"%s","log_dir":"%s","manifest":"/tests/groups.json","crate_dir":"%s","candidate_build":%s,"harness_build":%s,"fixture_ok":%s,"budget_exhausted":%s}\n' \
    "$step_num" "$step_tag" "$log_dir" "$crate_dir" \
    "$([ "$candidate_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$harness_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$fixture_ok" -eq 1 ] && echo true || echo false)" \
    "$([ "$budget_exhausted" -eq 1 ] && echo true || echo false)")

reward=$(printf '%s' "$score_input" | python3 /tests/score.py 2>"$log_dir/score.err")
score_status=$?

case "$reward" in
    0|0.*|1|1.0*) ;;
    *) reward='' ;;
esac

if [ "$score_status" -ne 0 ] || [ -z "$reward" ]; then
    fail_everything "the verifier could not score this step: score.py exited $score_status saying '$(tr -d '\n"\\' < "$log_dir/score.err" | tail -c 300)'. Nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    reported=1
    exit 0
fi

reported=1
report "$reward"
exit 0
